CREATE TABLE IF NOT EXISTS categories (id VARCHAR(64) PRIMARY KEY,name VARCHAR(120) NOT NULL,sort_order INT NOT NULL DEFAULT 0,active INT NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS products (id VARCHAR(64) PRIMARY KEY,sku VARCHAR(80) NOT NULL UNIQUE,category_id VARCHAR(64) NOT NULL,name VARCHAR(180) NOT NULL,name_en VARCHAR(180) NOT NULL,description TEXT NOT NULL,price BIGINT NOT NULL,compare_price BIGINT NOT NULL DEFAULT 0,stock INT NOT NULL DEFAULT 0,active INT NOT NULL DEFAULT 0,featured INT NOT NULL DEFAULT 0,images TEXT NOT NULL,revision INT NOT NULL DEFAULT 1,updated_at VARCHAR(30) NOT NULL,FOREIGN KEY(category_id) REFERENCES categories(id),CHECK(price>0),CHECK(stock>=0),CHECK(compare_price>=0));
CREATE TABLE IF NOT EXISTS settings (id VARCHAR(64) PRIMARY KEY,value TEXT NOT NULL,revision INT NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS coupons (code VARCHAR(40) PRIMARY KEY,kind VARCHAR(10) NOT NULL,amount BIGINT NOT NULL,min_total BIGINT NOT NULL DEFAULT 0,max_uses INT NOT NULL DEFAULT 0,used_count INT NOT NULL DEFAULT 0,active INT NOT NULL DEFAULT 1,expires_at VARCHAR(30) NOT NULL DEFAULT '',CHECK(amount>0),CHECK(used_count>=0));
CREATE TABLE IF NOT EXISTS orders (id VARCHAR(64) PRIMARY KEY,code VARCHAR(40) NOT NULL UNIQUE,idempotency VARCHAR(80) NOT NULL UNIQUE,request_hash VARCHAR(64) NOT NULL,tracking_hash VARCHAR(64) NOT NULL,name VARCHAR(120) NOT NULL,phone VARCHAR(20) NOT NULL,governorate VARCHAR(60) NOT NULL,address TEXT NOT NULL,note TEXT NOT NULL,subtotal BIGINT NOT NULL,discount BIGINT NOT NULL,shipping BIGINT NOT NULL,total BIGINT NOT NULL,coupon VARCHAR(40) NOT NULL DEFAULT '',status VARCHAR(20) NOT NULL DEFAULT 'new',attribution TEXT NOT NULL,consent INT NOT NULL DEFAULT 0,created_at VARCHAR(30) NOT NULL,updated_at VARCHAR(30) NOT NULL,CHECK(total>=0),CHECK(subtotal>=0),CHECK(shipping>=0),CHECK(discount>=0));
CREATE TABLE IF NOT EXISTS order_items (id VARCHAR(64) PRIMARY KEY,order_id VARCHAR(64) NOT NULL,product_id VARCHAR(64) NOT NULL,name VARCHAR(180) NOT NULL,sku VARCHAR(80) NOT NULL,price BIGINT NOT NULL,quantity INT NOT NULL,FOREIGN KEY(order_id) REFERENCES orders(id),FOREIGN KEY(product_id) REFERENCES products(id),CHECK(quantity>0),CHECK(price>0));
CREATE TABLE IF NOT EXISTS order_events (id VARCHAR(64) PRIMARY KEY,order_id VARCHAR(64) NOT NULL,status VARCHAR(20) NOT NULL,note TEXT NOT NULL,created_at VARCHAR(30) NOT NULL,FOREIGN KEY(order_id) REFERENCES orders(id));
CREATE TABLE IF NOT EXISTS stock_movements (id VARCHAR(64) PRIMARY KEY,product_id VARCHAR(64) NOT NULL,delta INT NOT NULL,reason VARCHAR(180) NOT NULL,created_at VARCHAR(30) NOT NULL,FOREIGN KEY(product_id) REFERENCES products(id));
CREATE TABLE IF NOT EXISTS sessions (id VARCHAR(64) PRIMARY KEY,csrf VARCHAR(64) NOT NULL,fingerprint VARCHAR(64) NOT NULL,expires_at VARCHAR(30) NOT NULL);
CREATE TABLE IF NOT EXISTS login_attempts (id VARCHAR(64) PRIMARY KEY,count INT NOT NULL,expires_at VARCHAR(30) NOT NULL);
CREATE TABLE IF NOT EXISTS outbox (id VARCHAR(80) PRIMARY KEY,order_id VARCHAR(64) NOT NULL,kind VARCHAR(20) NOT NULL,state VARCHAR(20) NOT NULL DEFAULT 'pending',attempts INT NOT NULL DEFAULT 0,last_error VARCHAR(120) NOT NULL DEFAULT '',created_at VARCHAR(30) NOT NULL,FOREIGN KEY(order_id) REFERENCES orders(id));
CREATE TABLE IF NOT EXISTS media (id VARCHAR(64) PRIMARY KEY,mime VARCHAR(30) NOT NULL,bytes LONGBLOB NOT NULL);
CREATE INDEX idx_orders_created ON orders(created_at);
CREATE INDEX idx_orders_status_created ON orders(status,created_at);
CREATE INDEX idx_items_order ON order_items(order_id);
CREATE INDEX idx_events_order ON order_events(order_id,created_at);
CREATE INDEX idx_outbox_state ON outbox(state,created_at);
CREATE INDEX idx_products_category ON products(category_id,active);
